type ResearchPlaceholderProps = {
  title: string;
  description: string;
};

export function ResearchPlaceholder({
  title,
  description,
}: ResearchPlaceholderProps) {
  return (
    <div className="mx-auto flex w-full max-w-3xl flex-col gap-3 px-4 py-12 md:px-6 md:py-16">
      <h1 className="font-display text-3xl tracking-tight">{title}</h1>
      <p className="text-muted-foreground">{description}</p>
    </div>
  );
}
import { getAuthenticatedUser } from "@/lib/auth";
import { isProSubscriberPlan } from "@/services/billing/userPlanAccess";
import { redirect } from "next/navigation";

/** Redirects signed-out users to sign-in and free users to pricing. */
export async function requireProSubscriber() {
  const user = await getAuthenticatedUser();

  if (!user) {
    redirect("/sign-in");
  }

  if (
    !isProSubscriberPlan(
      user.plan,
      user.subscription?.currentPeriodEnd ?? null,
    )
  ) {
    redirect("/pricing");
  }

  return user;
}
