"use client";

import {
  isFatalPollError,
  shouldScheduleNextPoll,
} from "@/services/news/newsRequestPollingLogic";
import type { NewsRequestResultPayload } from "@/services/news/newsRequestTypes";
import { useCallback, useEffect, useState } from "react";

export const NEWS_REQUEST_POLL_MS = 3000;

function normalizePollPayload(
  raw: NewsRequestResultPayload & { error?: string },
): NewsRequestResultPayload {
  return {
    newsRequest: raw.newsRequest,
    stories: Array.isArray(raw.stories) ? raw.stories : [],
  };
}

async function fetchNewsRequestResult(
  newsRequestId: string,
  signal?: AbortSignal,
): Promise<NewsRequestResultPayload> {
  const response = await fetch(`/api/news/${newsRequestId}`, {
    cache: "no-store",
    headers: { Accept: "application/json" },
    signal,
  });
  const payload = (await response.json()) as NewsRequestResultPayload & {
    error?: string;
  };

  if (!response.ok) {
    throw new Error(payload.error ?? "Failed to load news request");
  }

  return normalizePollPayload(payload);
}

export function useNewsRequestPolling(newsRequestId: string | undefined) {
  const [data, setData] = useState<NewsRequestResultPayload | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pollWarning, setPollWarning] = useState<string | null>(null);
  const [pollEpoch, setPollEpoch] = useState(0);

  const refresh = useCallback(async () => {
    if (!newsRequestId) {
      return null;
    }
    const payload = await fetchNewsRequestResult(newsRequestId);
    setData(payload);
    setError(null);
    return payload;
  }, [newsRequestId]);

  const restartPolling = useCallback(() => {
    setError(null);
    setPollWarning(null);
    setPollEpoch((value) => value + 1);
  }, []);

  useEffect(() => {
    if (!newsRequestId) {
      return;
    }
    const requestId: string = newsRequestId;

    const abortController = new AbortController();
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    async function poll() {
      if (cancelled) {
        return;
      }
      try {
        const payload = await fetchNewsRequestResult(
          requestId,
          abortController.signal,
        );
        if (cancelled) {
          return;
        }
        setPollWarning(null);
        setError(null);
        setData(payload);
        if (
          shouldScheduleNextPoll({
            status: payload.newsRequest.status,
            isRerunning: payload.newsRequest.isRerunning,
          })
        ) {
          timer = setTimeout(poll, NEWS_REQUEST_POLL_MS);
        }
      } catch (pollError) {
        if (cancelled) {
          return;
        }
        if (
          pollError instanceof DOMException &&
          pollError.name === "AbortError"
        ) {
          return;
        }
        const message =
          pollError instanceof Error ? pollError.message : "Polling failed";
        if (isFatalPollError(message)) {
          setError(message);
          return;
        }
        setPollWarning(
          "Connection issue — still checking your request in the background…",
        );
        timer = setTimeout(poll, NEWS_REQUEST_POLL_MS);
      }
    }

    void poll();

    return () => {
      cancelled = true;
      abortController.abort();
      if (timer) {
        clearTimeout(timer);
      }
    };
  }, [newsRequestId, pollEpoch]);

  const status = data?.newsRequest.status;

  return {
    data,
    setData,
    error,
    pollWarning,
    refresh,
    restartPolling,
    /** True until the first successful GET for this id (or a fatal error). */
    isLoading: Boolean(newsRequestId) && data === null && error === null,
    isPending: status === "pending",
    isSuccess: status === "success",
    isFailed: status === "failed",
  };
}
"use client";

import { cn } from "@/lib/utils";
import { Loader2 } from "lucide-react";
import { useEffect, useMemo, useState } from "react";

export const NEWS_STORIES_LOADING_MESSAGES = [
  "Gathering community stories…",
  "Ranking by upvotes…",
  "Scanning recent headlines…",
  "Finding what readers saved…",
  "Pulling sources together…",
  "Sorting the briefing feed…",
] as const;

export const NEWS_STORY_LOADING_MESSAGES = [
  "Opening this story…",
  "Loading sources and takeaways…",
  "Preparing the deep dive…",
  "Checking community votes…",
] as const;

export const NEWS_REQUEST_LOADING_MESSAGES = [
  "Checking your briefing status…",
  "Syncing pipeline progress…",
  "Loading your stories…",
  "Reviewing research steps…",
] as const;

export const NEWS_BRIEFING_OVERDUE_MESSAGES = [
  "Will be ready any time…",
  "AI is working on your briefing…",
  "Still reading sources…",
  "Wrapping up the last research pass…",
  "This usually finishes shortly…",
] as const;

export const CHAT_LOADING_MESSAGES = [
  "Searching trusted sources…",
  "Reading recent coverage…",
  "Cross-checking market context…",
  "Drafting your answer…",
  "Following the research trail…",
] as const;

export const CHAT_RESEARCH_OVERDUE_MESSAGES = [
  "Will be done any moment…",
  "Filtering the stories…",
  "Doing deeper research…",
  "Cross-checking sources…",
  "Almost there…",
] as const;

export const TRENDING_LOADING_MESSAGES = [
  "Finding what’s trending…",
  "Tallying community upvotes…",
  "Surfacing this week’s topics…",
] as const;

function pickNextMessage(messages: readonly string[], current: string): string {
  if (messages.length === 0) {
    return "Loading…";
  }
  if (messages.length === 1) {
    return messages[0]!;
  }
  let next = messages[Math.floor(Math.random() * messages.length)]!;
  let attempts = 0;
  while (next === current && attempts < 10) {
    next = messages[Math.floor(Math.random() * messages.length)]!;
    attempts += 1;
  }
  return next;
}

type ShimmerLoadingStatusProps = {
  messages?: readonly string[];
  className?: string;
  statusLabel?: string;
  layout?: "inline" | "page" | "panel";
};

export function ShimmerLoadingStatus({
  messages = NEWS_STORIES_LOADING_MESSAGES,
  className,
  statusLabel = "Loading",
  layout = "page",
}: ShimmerLoadingStatusProps) {
  const pool = useMemo(() => [...messages], [messages]);
  const initialPhrase = pool[0] ?? "Loading…";
  const [phrase, setPhrase] = useState(initialPhrase);

  useEffect(() => {
    if (pool.length < 2) {
      return;
    }
    const interval = window.setInterval(() => {
      setPhrase((current) => pickNextMessage(pool, current));
    }, 2_600);
    return () => window.clearInterval(interval);
  }, [pool]);

  const body = (
    <div
      className={cn(
        "flex items-center gap-2.5",
        layout === "page" || layout === "panel"
          ? "flex-col text-center"
          : undefined,
      )}
    >
      <Loader2
        className="size-5 shrink-0 animate-spin text-muted-foreground"
        aria-hidden
      />
      <p className="shimmer-loading-text max-w-sm text-sm font-medium">
        {phrase}
      </p>
    </div>
  );

  if (layout === "inline") {
    return (
      <div
        className={cn(className)}
        role="status"
        aria-live="polite"
        aria-label={statusLabel}
      >
        {body}
      </div>
    );
  }

  if (layout === "panel") {
    return (
      <div
        className={cn("flex justify-center py-6", className)}
        role="status"
        aria-live="polite"
        aria-label={statusLabel}
      >
        {body}
      </div>
    );
  }

  return (
    <main
      className={cn(
        "flex min-h-0 flex-1 flex-col items-center justify-center overflow-y-auto bg-background px-4 py-12",
        className,
      )}
      role="status"
      aria-live="polite"
      aria-label={statusLabel}
    >
      {body}
    </main>
  );
}
