content.content:
  instrument: StockResearchInstrument,
  userPrompt: string,
): ToolDeterminerModelOutput {
  if (!wantsDeepResearch(userPrompt)) {
    return flags;
  }

  const upstox = { ...flags.upstox };
  const serp = { ...flags.serp };

  upstox.getFullMarketQuotes = true;
  upstox.getLtpQuotes = true;
  upstox.getOhlcQuotes = true;
  upstox.getHistoricalCandles = true;
  upstox.getInstrumentNews = true;

  serp.searchGoogleFinance = true;
  serp.searchGoogleNews = true;
  serp.searchGoogleNewsTab = true;
  serp.searchGoogle = true;

  if (isEquityWithIsin(instrument)) {
    upstox.getCompanyProfile = true;
    upstox.getKeyRatios = true;
    upstox.getShareHoldings = true;
    upstox.getIncomeStatement = true;
    upstox.getBalanceSheet = true;
    upstox.getCashFlow = true;
    upstox.getCorporateActions = true;
    upstox.getCompetitors = true;
  }

  if (isDerivative(instrument)) {
    upstox.getOptionChain = true;
    upstox.getOptionContracts = true;
    upstox.getOpenInterest = true;
    upstox.getChangeInOpenInterest = true;
    upstox.getMaxPain = true;
    upstox.getPutCallRatio = true;
    upstox.getOptionGreeks = true;
    upstox.getIntradayCandles = true;
  }

  upstox.getFiiData = true;
  upstox.getDiiData = true;
  upstox.getExchangeStatus = true;
  upstox.getMarketTimings = true;

  upstox.authorizeMarketDataFeed = false;
  upstox.createMarketDataStreamer = false;

  return { ...flags, upstox, serp };
}

function buildUpstoxCatalog(): string {
  return UPSTOX_DETERMINER_TOOL_KEYS.map((key) => {
    const entry = upstoxApis[key];
    return [
      `### ${key}`,
      entry.detailedDescription,
      `Input: ${entry.input}`,
      `Output: ${entry.output}`,
    ].join("\n");
  }).join("\n\n");
}

function buildSerpCatalog(): string {
  return SERP_DETERMINER_TOOL_KEYS.map((key) => {
    const entry = serpEngines[key];
    return [`### ${key}`, entry.description].join("\n");
  }).join("\n\n");
}

function buildToolDeterminerSystemPrompt(): string {
  return [
    "You are a tool determiner for stock investment research.",
    "The user chose a specific instrument and wants investment-oriented research with as much relevant detail as practical.",
    "Return boolean flags for each Upstox API and each Serp engine: true = pipeline should call it, false = skip.",
    "Prefer true for tools that add non-duplicative facts (price, fundamentals, news, derivatives analytics, web context).",
    "Avoid redundant calls (e.g. do not enable both getFullMarketQuotes and getLtpQuotes unless both add value; default to getFullMarketQuotes + getOhlcQuotes for equities).",
    "Never enable authorizeMarketDataFeed or createMarketDataStreamer unless the user explicitly asks for live streaming quotes.",
    "For listed equities with ISIN: enable fundamentals (profile, ratios, holdings, statements, corporate actions, competitors) when the user wants to invest or requests depth.",
    "For derivatives (FUT/CE/PE): prioritize option chain, OI/change OI, max pain, PCR, greeks, intraday/historical candles; skip equity fundamentals without ISIN.",
    "Use Serp for narrative news, analyst/web context, Google Finance page, and AI-mode synthesis when helpful.",
    "Set searchGoogleMaps* false unless the user asks about branches/locations.",
    "Set searchYoutubeVideoTranscript false unless video/transcript evidence is needed.",
    "Include macro context (getFiiData, getDiiData) when evaluating market-wide flows relevant to the thesis.",
    "Provide concise reasoning summarizing why groups of tools were enabled.",
    "",
    "## Upstox tools",
    buildUpstoxCatalog(),
    "",
    "## Serp tools",
    buildSerpCatalog(),
  ].join("\n");
}

export function buildToolDeterminerResultFromModelOutput(
  raw: ToolDeterminerModelOutput,
  instrument: StockResearchInstrument,
  options: { model?: string; userPrompt?: string } = {},
): ToolDeterminerResult {
  const adjusted = options.userPrompt
    ? applyInvestResearchMinimums(raw, instrument, options.userPrompt)
    : raw;

  return {
    reasoning: adjusted.reasoning,
    upstox: adjusted.upstox as UpstoxToolFlags,
    serp: adjusted.serp as SerpToolFlags,
    instrument,
    model: options.model ?? "test-model",
  };
}

export function countEnabledTools(result: ToolDeterminerResult): {
  upstox: number;
  serp: number;
  total: number;
} {
  const upstox = UPSTOX_DETERMINER_TOOL_KEYS.filter((k) => result.upstox[k])
    .length;
  const serp = SERP_DETERMINER_TOOL_KEYS.filter((k) => result.serp[k]).length;
  return { upstox, serp, total: upstox + serp };
}

async function runToolDeterminerCore(
  params: ToolDeterminerAgentParams,
  generate: typeof aiClient.generate,
): Promise<ToolDeterminerResult> {
  const instrument = normalizeStockResearchInstrument(params.instrument);
  const model = resolveToolDeterminerModel(params.model);

  const raw = await generate({
    model,
    system: params.system ?? buildToolDeterminerSystemPrompt(),
    prompt: params.userPrompt,
    extraContext: {
      instrument,
      investIntent: wantsDeepResearch(params.userPrompt),
      isEquityWithIsin: isEquityWithIsin(instrument),
      isDerivative: isDerivative(instrument),
    },
    schemaName: "StockResearchToolDeterminerOutput",
    schemaDescription:
      "Boolean flags for each Upstox and Serp tool key, plus reasoning.",
    output: toolDeterminerModelOutputSchema,
    temperature: 0,
    maxOutputTokens: 4096,
    abortSignal: params.abortSignal,
  });

  return buildToolDeterminerResultFromModelOutput(raw, instrument, {
    model,
    userPrompt: params.userPrompt,
  });
}

export function createToolDeterminerAgent(options: AIClientOptions = {}) {
  const client = createAIClient(options);

  return async function toolDeterminerAgent(
    params: ToolDeterminerAgentParams,
  ): Promise<ToolDeterminerResult> {
    return await runToolDeterminerCore(params, client.generate.bind(client));
  };
}

export async function runToolDeterminerAgent(
  params: ToolDeterminerAgentParams,
): Promise<ToolDeterminerResult> {
  return await runToolDeterminerCore(params, aiClient.generate.bind(aiClient));
}
/**
 * Query enhancer agent (conversational query rewrite)
 *
 * Role:
 * Produce a standalone research query from the current user message by fixing grammar and
 * resolving pronouns/references **only when** recent chat context is required. Does not
 * invent dates, tickers, or entities that the user did not supply in the current turn.
 *
 * Called from:
 * - `runSmallDeterminerAgent` before Serp tool planning (skipped when `isNewsStory` deep dive)
 * - `inngest/chatPipeline.ts` indirect via determiner step
 *
 * Model: `QUERY_ENHANCER_MODEL` → `OPENAI_MODEL` → `gpt-4o-mini`.
 *
 * Input:
 * - `query` — raw user text for this turn
 * - Optional `recentMessages` — up to 10 prior turns (`formatRecentMessagesForEnhancer`)
 * - Optional `model`, `system`, `abortSignal`
 *
 * Output: Single enhanced query string (plain text, no JSON wrapper).
 *
 * Does not: choose Serp engines, scrape pages, or apply guardrails (runs after guardrails pass).
 */

import { aiClient, createAIClient, type AIClientOptions } from "@/clients/AIClient";
import { resolveOpenAiModelId } from "@/lib/openAiModel";
import { z } from "zod";

const RECENT_MESSAGE_LIMIT = 10;
const RECENT_MESSAGE_CHARS = 500;

const recentMessageSchema = z.object({
  role: z.string().min(1),
  content: z.string().min(1),
});

export const queryEnhancerParamsSchema = z.object({
  /** Raw user query before search or routing. */
  query: z.string().min(1),
  recentMessages: z.array(recentMessageSchema).max(RECENT_MESSAGE_LIMIT).optional(),
  model: z.string().min(1).optional(),
  system: z.string().min(1).optional(),
});

export type QueryEnhancerParams = z.input<typeof queryEnhancerParamsSchema> & {
  abortSignal?: AbortSignal;
};

export const enhancedQuerySchema = z.string().min(1).max(2000);

const modelOutputSchema = z.object({
  enhancedQuery: z.string().min(1).max(2000),
});

function resolveQueryEnhancerModel(override?: string): string {
  return resolveOpenAiModelId(override, process.env.QUERY_ENHANCER_MODEL);
}

/** Same trimming convention as the small determiner recent-message context. */
export function formatRecentMessagesForEnhancer(
  messages?: Array<{ role: string; content: string }>,
): Array<{ role: string; content: string }> | undefined {
  if (!messages || messages.length === 0) {
    return undefined;
  }

  return messages.slice(-RECENT_MESSAGE_LIMIT).flatMap((message) => {
    const role = message.role.trim();
    const content = message.content.trim().slice(0, RECENT_MESSAGE_CHARS);
    if (!role || !content) {
      return [];
    }
    return [{ role, content }];
  });
}

function buildSystemPrompt(): string {
  return [
    "You are a query enhancement agent for a financial and economic research product.",
    "",
    "Take the current user query and return a corrected, clearer version suitable for search/research routing.",
    "",
    "Recent messages (when provided) are context for resolving references — NOT facts to automatically inherit.",
    "The current user message is authoritative.",
    "Use previous conversation only when necessary to understand what the current message refers to.",
    "If the current message is independently understandable, treat it as a self-contained query and do not inject previous topic constraints.",
    "Never manufacture missing temporal, numerical, entity, geographic, or factual constraints from previous messages.",
    "When uncertain whether context should be inherited, prefer the conservative interpretation: preserve the current query rather than adding an unsupported constraint.",
    "",
    "Context resolution (use recent messages): incomplete follow-ups or pronouns/references such as \"what about diesel?\", \"what did they say about it?\", \"explain the second point\", \"tell me more about that\", \"what is its current debt?\" when \"its\" must be resolved.",
    "",
    "Independent query (do NOT inject prior topic constraints): the current message already names a recognizable standalone topic, e.g. \"What are India's diesel export figures?\", \"What is Reliance's current stock price?\" even if a different year or topic was discussed earlier.",
    "",
    "NEVER automatically inherit from previous messages unless the current message explicitly needs it:",
    "years, dates, months, quarters, financial years, prices, percentages, quantities, \"latest\"/\"current\" qualifiers, locations, companies, people, events, or status.",
    "",
    "Example — do NOT inherit year:",
    "Prior: India crude oil dependency in 2023. Current: What are India's diesel export figures?",
    "Output: India's diesel export figures (NOT \"in 2023\").",
    "",
    "Example — DO inherit when resolving reference:",
    "Prior: India crude oil dependency in 2026. Current: What about diesel?",
    "Output: India's diesel exports/imports in 2026.",
    "",
    "Explicit information in the current message always wins over previous context.",
    "Preserve temporal words from the current message exactly: latest, current, today, this year, last year, 2026, FY2025-26, etc.",
    "Do not replace them with dates/years from earlier turns.",
    "",
    "Tasks:",
    "- Fix grammar and spelling mistakes.",
    "- Correct obvious typos in company names and financial terminology when intent is clear.",
    "- Resolve genuine conversational references only when needed.",
    "- Preserve ambiguity when the user did not specify a constraint (do not pick a year for them).",
    "- Do not answer the question, perform research, or add new facts.",
    "- Do not unnecessarily rewrite correctly written text.",
    "",
    "Output only the enhanced query text in the enhancedQuery field.",
    "No explanations, notes, Markdown, or commentary.",
  ].join("\n");
}

