      );
      await Promise.all(
        persistRows.map((row) =>
          upsertStockResearchResourceByHash({
            stockResearchId: input.stockResearchId,
            provider: row.provider,
            type: row.resourceType,
            title: row.title,
            externalId: row.externalId,
