                  >
                    <p className="line-clamp-1 text-sm font-medium leading-snug">
                      {formatStockResearchTitle(research)}
                    </p>
                    <p className="mt-1 line-clamp-2 text-xs text-muted-foreground">
                      {research.userPrompt ?? research.query}
